var path = "Assets/Resources/UI/SaveSlotPanel.prefab";
var go = AssetDatabase.LoadAssetAtPath<GameObject>(path);
if (go == null) return "PREFAB NOT FOUND: " + path;
var sb = new System.Text.StringBuilder();
sb.Append("prefab root: ").Append(go.name).Append("\n");
foreach (var rt in go.GetComponentsInChildren<RectTransform>(true))
{
    string p = rt.name;
    var t = rt.parent;
    while (t != null) { p = t.name + "/" + p; t = t.parent; }
    var ap = rt.anchoredPosition;
    var sd = rt.sizeDelta;
    sb.Append(p)
      .Append(" | anchored=").Append(ap.x).Append(",").Append(ap.y)
      .Append(" | sizeDelta=").Append(sd.x).Append(",").Append(sd.y)
      .Append(" | active=").Append(rt.gameObject.activeSelf)
      .Append("\n");
}
return sb.ToString();
